/// <summary>
/// PaffH 15.04.25
/// </summary>
/// <param name="sender">Common</param>
/// <param name="e">DataEventArgs</param>
[DataEventHandler(tableStr(InventItemSalesSetup), DataEventType::Updating)
    ,SuppressBPWarning('BPParameterNotUsed', '"e" is not used')]
public static void InventItemSalesSetup_onUpdating(Common sender, DataEventArgs e)
{
    InventItemSalesSetup inventItemSalesSetup = sender as InventItemSalesSetup;
    for (int i = 1; i <= 4; i++)
    {
        FieldId fieldnum1;
        switch (i)
        {
            case 1:
                fieldnum1 = fieldNum(InventItemSalesSetup, MultipleQty);
                break;
            case 2:
                fieldnum1 = fieldNum(InventItemSalesSetup, LowestQty);
                break;
            case 3:
                fieldnum1 = fieldNum(InventItemSalesSetup, HighestQty);
                break;
            case 4:
                fieldnum1 = fieldNum(InventItemSalesSetup, StandardQty);
                break;
        }
        if (inventItemSalesSetup.orig().(fieldnum1) != inventItemSalesSetup.(fieldnum1))
        {
            // save changeLog POP specific Datamanagement
            NDXPOPspecificDataManagementHistory::saveChangeFromInventTable(
                inventItemSalesSetup.inventTable().RecId
                , inventItemSalesSetup
                , fieldnum1
                , [inventItemSalesSetup.orig().(fieldnum1)]
                , [inventItemSalesSetup.(fieldnum1)]);
        }
    }
}
